};
window.decryptAES = function (encryptedStr) {
    // 注意：与后端SECRET_KEY完全一致（需保证编码一致，这里用UTF-8）
    const SECRET_KEY = '0123456789abcdef0123456789abcdef';
    // 步骤1：按分号分割，得到 IV 的 Base64 和 密文的 Base64
    const [ivBase64, ciphertextBase64] = encryptedStr.split(';');
    if (!ivBase64 || !ciphertextBase64) {
        throw new Error('加密字符串格式错误，缺少IV或密文');
    }
    // 步骤2：Base64解码（IV 和 密文分别解码）
    const iv = CryptoJS.enc.Base64.parse(ivBase64); // 解码IV
    const ciphertext = CryptoJS.enc.Base64.parse(ciphertextBase64); // 解码密文
    const key = CryptoJS.enc.Utf8.parse(SECRET_KEY); // 密钥按UTF-8编码（与后端一致）

    // 步骤3：AES-CBC-PKCS5Padding 解密（算法必须和后端完全匹配）
    const decrypted = CryptoJS.AES.decrypt(
        { ciphertext: ciphertext }, // 密文对象
        key, // 固定密钥
        {
            iv: iv, // 解码后的随机IV
            mode: CryptoJS.mode.CBC,
            padding: CryptoJS.pad.Pkcs7
        }
    );

    // 步骤4：将解密结果转为UTF-8字符串（与后端加密时的编码一致）
    return decrypted.toString(CryptoJS.enc.Utf8);
}

window.cmp_privacyurl = "https://chintglobal.com/global/en/about-us/privacy-policy.html"
var locationHref1 = chintGlobal.currentPath;
var locationHref1Splite1 = decryptAES(locationHref1).split("/");
var lanloc1 = '';
if (decryptAES(locationHref1).includes("/global/en") || decryptAES(locationHref1).includes("/ae/en") || decryptAES(locationHref1).includes("/fr/en")
    || decryptAES(locationHref1).includes("/fr/fr") || decryptAES(locationHref1).includes("/sa/en") || decryptAES(locationHref1).includes("/nl/en")
    || decryptAES(locationHref1).includes("/nl/nl") || decryptAES(locationHref1).includes("/sg/en")
    || decryptAES(locationHref1).includes("/ph/en") || decryptAES(locationHref1).includes("/content/experience-fragments")
    || decryptAES(locationHref1).includes("/co/es") || decryptAES(locationHref1).includes("/co/en")
    || decryptAES(locationHref1).includes("/au/en") || decryptAES(locationHref1).includes("/gb/en")
    || decryptAES(locationHref1).includes("/br/en") || decryptAES(locationHref1).includes("/br/pt")
    || decryptAES(locationHref1).includes("/in/en") || decryptAES(locationHref1).includes("/eg/en")
    || decryptAES(locationHref1).includes("/eg/ar") || decryptAES(locationHref1).includes("/dg/en")
    || decryptAES(locationHref1).includes("/dg/ar") || decryptAES(locationHref1).includes("/ke/en") ) {
    if (decryptAES(locationHref1).lastIndexOf("/content/chintsite") > -1) {
        if (locationHref1Splite1.length > 4) {
            lanloc1 = "/"+locationHref1Splite1[3]+"/"+locationHref1Splite1[4]+"/";
        }
    } else {
        lanloc1 = "/"+locationHref1Splite1[1]+"/"+locationHref1Splite1[2]+"/";
    }
    if (lanloc1 !== "/global/en/") {
        window.cmp_privacyurl = window.cmp_privacyurl.replace('/global/en/', lanloc1);
    }
}

