$('.popup-container .popup_form_subscribe').attr('data-formid', window.subscribeFormId)
$('.subscribeForm').each(function () {
    $(this).attr('data-formid', window.subscribeFormId);
});
$('.contactForm').each(function () {
    $(this).attr('data-formid', window.contactFormId);
});
var formIdValue = [];
formIdValue.push(window.contactFormId);
formIdValue.push(window.subscribeFormId);
var mktoFormConfig = {
    podId: "//content.chintglobal.com",
    munchkinId: "390-XGM-084",
    formIds: formIdValue
};


/* ---- NO NEED TO TOUCH ANYTHING BELOW THIS LINE! ---- */

function mktoFormChain(config) {

    /* util */
    var arrayify = getSelection.call.bind([].slice);

    /* const */
    var MKTOFORM_ID_ATTRNAME = "data-formId";

    /* fix inter-form label bug! */
    MktoForms2.whenRendered(function (form) {
        var formEl = form.getFormElem()[0],
            rando = "_" + new Date().getTime() + Math.random();

        arrayify(formEl.querySelectorAll("label[for]"))
            .map(function (labelEl) {
                return {
                    label: labelEl,
                    for: formEl.querySelector('[id="' + labelEl.htmlFor + '"]')
                }
            })
            .forEach(function (labelDesc) {
                if (labelDesc.for) {
                    if (!labelDesc.for.hasAttribute("data-uniquified")) {
                        labelDesc.for.id = labelDesc.for.id + rando;
                        labelDesc.for.setAttribute("data-uniquified", "true");
                    }
                    labelDesc.label.htmlFor = labelDesc.for.id;
                }
            });
    });

    /* chain, ensuring only one #mktoForm_nnn exists at a time */
    arrayify(config.formIds).forEach(function (formId) {
        var loadForm = MktoForms2.loadForm.bind(MktoForms2, config.podId, config.munchkinId, formId),
            formEls = arrayify(document.querySelectorAll("[" + MKTOFORM_ID_ATTRNAME + '="' + formId + '"]'));
        if (formEls.length > 0) {
            (function loadFormCb(formEls) {
                var formEl = formEls.shift();
                formEl.id = "mktoForm_" + formId;

                loadForm(function (form) {
                    formEl.id = "";
                    if (formEls.length) {
                        loadFormCb(formEls);
                    }
                });
            })(formEls);
        }
    });
}

setTimeout(() => {
    $("form.mktoForm").addClass("width95");
}, 999);
setTimeout(() => {
    mktoFormChain(mktoFormConfig);
}, 1000);
